videoStage(parent = null) {
    this.observeComponentCreation2((elmtId, isInitialRender) => {
        Stack.create({ alignContent: Alignment.TopStart });
        Stack.width(Math.max(1, this.workspaceLayout().video.width));
        Stack.height(Math.max(1, this.workspaceLayout().video.height));
        Stack.position({ x: this.workspaceLayout().video.x, y: this.workspaceLayout().video.y });
        Stack.visibility(this.videoMode && this.workspaceLayout().video.width > 0 ? Visibility.Visible : Visibility.Hidden);
        Stack.backgroundColor('#000000');
        Stack.zIndex(this.videoFullscreen ? 20 : this.videoFloating ? 10 : 1);
        Stack.clip(true);
    }, Stack);
    this.observeComponentCreation2((elmtId, isInitialRender) => {
        // This exact Surface is unconditional. Only its bounds change.
        XComponent.create({ id: 'mfp-native-video', type: 'surface', controller: this.videoSurface }, "com.multifunplayer.ohos/entry");
        // This exact Surface is unconditional. Only its bounds change.
        XComponent.width('100%');
        // This exact Surface is unconditional. Only its bounds change.
        XComponent.height(this.videoPictureHeight());
        // This exact Surface is unconditional. Only its bounds change.
        XComponent.backgroundColor('#000000');
        // This exact Surface is unconditional. Only its bounds change.
        XComponent.hitTestBehavior(HitTestMode.None);
        // This exact Surface is unconditional. Only its bounds change.
        XComponent.zIndex(0);
        // This exact Surface is unconditional. Only its bounds change.
        XComponent.onLoad(() => this.surfaceChanged(this.videoSurface.getXComponentSurfaceId(), true));
    }, XComponent);
    this.observeComponentCreation2((elmtId, isInitialRender) => {
        // Gestures live on ArkUI, never on the native Surface or the chrome parent.
        Column.create();
        // Gestures live on ArkUI, never on the native Surface or the chrome parent.
        Column.width('100%');
        // Gestures live on ArkUI, never on the native Surface or the chrome parent.
        Column.height(this.videoPictureHeight());
        // Gestures live on ArkUI, never on the native Surface or the chrome parent.
        Column.justifyContent(FlexAlign.Start);
        // Gestures live on ArkUI, never on the native Surface or the chrome parent.
        Column.backgroundColor('#00000000');
        // Gestures live on ArkUI, never on the native Surface or the chrome parent.
        Column.hitTestBehavior(HitTestMode.Block);
        // Gestures live on ArkUI, never on the native Surface or the chrome parent.
        Column.zIndex(1);
        // Gestures live on ArkUI, never on the native Surface or the chrome parent.
        Column.accessibilityText('视频画面：单击暂停或继续；浮窗可拖动');
        globalThis.Gesture.create(GesturePriority.Low);
        GestureGroup.create(GestureMode.Exclusive);
        PanGesture.create({ fingers: 1, direction: PanDirection.All, distance: 8 });
        PanGesture.onActionStart(this.videoGestureHandler('start'));
        PanGesture.onActionUpdate(this.videoGestureHandler('update'));
        PanGesture.onActionEnd(this.videoGestureHandler('end'));
        PanGesture.onActionCancel(this.videoGestureHandler('cancel'));
        PanGesture.pop();
        TapGesture.create({ count: 1, fingers: 1 });
        TapGesture.onAction(this.videoGestureHandler('tap'));
        TapGesture.pop();
        GestureGroup.pop();
        globalThis.Gesture.pop();
    }, Column);
    this.observeComponentCreation2((elmtId, isInitialRender) => {
        Text.create(this.videoPlaybackStatus());
        Text.fontSize(14);
        Text.fontColor('#FFFFFF');
        Text.backgroundColor('#66000000');
        Text.padding(4);
        Text.visibility(this.videoFloating || this.videoControlsVisible ? Visibility.Visible : Visibility.Hidden);
        Text.hitTestBehavior(HitTestMode.None);
    }, Text);
    Text.pop();
    // Gestures live on ArkUI, never on the native Surface or the chrome parent.
    Column.pop();
    this.observeComponentCreation2((elmtId, isInitialRender) => {
        Column.create({ space: 0 });
        Column.width('100%');
        Column.height(this.workspaceLayout().controlsHeight);
        Column.backgroundColor(UiStyle.page);
        Column.position({ x: 0, y: Math.max(0, this.workspaceLayout().video.height - this.workspaceLayout().controlsHeight) });
        Column.visibility(!this.videoFullscreen || this.videoControlsVisible ? Visibility.Visible : Visibility.Hidden);
        Column.hitTestBehavior(HitTestMode.Default);
        Column.zIndex(2);
        Column.clip(true);
    }, Column);
    this.observeComponentCreation2((elmtId, isInitialRender) => {
        Row.create({ space: 0 });
        Row.width('100%');
        Row.height(52);
        Row.hitTestBehavior(HitTestMode.Default);
    }, Row);
    this.observeComponentCreation2((elmtId, isInitialRender) => {
        Button.createWithLabel(this.videoActionPending ? '…' : this.playing ? '暂停' : this.videoState === 'completed' ? '重播' : '播放');
        __Button__flatButton();
        Button.width(this.videoFloating ? '50%' : 64);
        Button.height(52);
        Button.padding(4);
        Button.fontSize(16);
        Button.backgroundColor(UiStyle.accent);
        Button.fontColor('#FFFFFF');
        Button.enabled(this.videoCanToggle());
        Button.accessibilityText(this.playing ? '暂停视频' : '播放视频');
        Button.onClick(() => { void this.videoPlaybackAction(); });
    }, Button);
    Button.pop();
    this.observeComponentCreation2((elmtId, isInitialRender) => {
        If.create();
        if (this.videoFloating && !this.videoFullscreen) {
            this.ifElseBranchUpdateFunction(0, () => {
                this.observeComponentCreation2((elmtId, isInitialRender) => {
                    Button.createWithLabel('展开');
                    __Button__flatButton();
                    Button.width('50%');
                    Button.height(52);
                    Button.padding(4);
                    Button.fontSize(16);
                    Button.onClick(() => this.setVideoFloating(false));
                }, Button);
                Button.pop();
            });
        }
        else {
            this.ifElseBranchUpdateFunction(1, () => {
                this.observeComponentCreation2((elmtId, isInitialRender) => {
                    Button.createWithLabel('■');
                    __Button__flatButton();
                    Button.width(52);
                    Button.height(52);
                    Button.padding(4);
                    Button.backgroundColor(UiStyle.danger);
                    Button.fontColor('#FFFFFF');
                    Button.accessibilityText('停止输出和播放');
                    Button.onClick(() => this.stop());
                }, Button);
                Button.pop();
                this.observeComponentCreation2((elmtId, isInitialRender) => {
                    If.create();
                    if (this.currentScreen !== 'player') {
                        this.ifElseBranchUpdateFunction(0, () => {
                            this.observeComponentCreation2((elmtId, isInitialRender) => {
                                Button.createWithLabel('浮窗');
                                __Button__flatButton();
                                Button.width(56);
                                Button.height(52);
                                Button.padding(4);
                                Button.fontSize(16);
                                Button.onClick(() => this.setVideoFloating(true));
                            }, Button);
                            Button.pop();
                        });
                    }
                    else {
                        this.ifElseBranchUpdateFunction(1, () => {
                        });
                    }
                }, If);
                If.pop();
                this.observeComponentCreation2((elmtId, isInitialRender) => {
                    Button.createWithLabel(this.videoFullscreen ? '退出' : '全屏');
                    __Button__flatButton();
                    Button.layoutWeight(1);
                    Button.height(52);
                    Button.padding(4);
                    Button.fontSize(16);
                    Button.accessibilityText(this.videoFullscreen ? (this.presentationMode === 'native-fullscreen' ? '退出系统全屏' : '退出窗口内全屏') : '全屏');
                    Button.onClick(() => this.setVideoFullscreen(!this.videoFullscreen));
                }, Button);
                Button.pop();
            });
        }
    }, If);
    If.pop();
    Row.pop();
    this.observeComponentCreation2((elmtId, isInitialRender) => {
        Canvas.create(this.playerCanvas);
        Canvas.width('100%');
        Canvas.height(36);
        Canvas.onReady(() => this.drawTrace());
        Canvas.onAreaChange(() => this.drawTrace());
        Canvas.onClick((event: ClickEvent) => { this.cancelVideoChromeTimer(); this.seekTransport(Math.max(0, Math.min(1, event.x / Math.max(1, this.playerCanvas.width))) * this.durationMs); this.scheduleVideoChromeHide(); });
    }, Canvas);
    Canvas.pop();
    this.observeComponentCreation2((elmtId, isInitialRender) => {
        If.create();
        if (this.workspaceLayout().controlsHeight >= 136) {
            this.ifElseBranchUpdateFunction(0, () => {
                this.observeComponentCreation2((elmtId, isInitialRender) => {
                    Row.create({ space: 8 });
                    Row.padding({ left: 8, right: 8 });
                    Row.width('100%');
                    Row.height(48);
                }, Row);
                this.observeComponentCreation2((elmtId, isInitialRender) => {
                    Slider.create({ value: this.positionMs, min: 0, max: Math.max(1, this.durationMs), step: 1 });
                    Slider.attributeModifier.bind(this)(new MfpSliderMaterialModifier(this.materialRevision));
                    Slider.layoutWeight(1);
                    Slider.height(48);
                    Slider.selectedColor(UiStyle.accent);
                    Slider.trackColor(UiStyle.edge);
                    Slider.blockColor(UiStyle.accent);
                    Slider.enabled(this.videoReady && !this.importing && !this.openingVideo && !this.libraryBusy);
                    Slider.onChange((value: number, mode: SliderChangeMode) => {
                        this.cancelVideoChromeTimer();
                        this.seekTransport(value);
                        if (mode === SliderChangeMode.End || mode === SliderChangeMode.Click) {
                            this.scheduleVideoChromeHide();
                        }
                    });
                }, Slider);
                this.observeComponentCreation2((elmtId, isInitialRender) => {
                    Text.create((this.positionMs / 1000).toFixed(1) + ' / ' + (this.durationMs / 1000).toFixed(1) + ' s');
                    Text.fontSize(14);
                    Text.fontColor(UiStyle.muted);
                    Text.maxLines(1);
                }, Text);
                Text.pop();
                Row.pop();
            });
        }
        else {
            this.ifElseBranchUpdateFunction(1, () => {
            });
        }
    }, If);
    If.pop();
    Column.pop();
    Stack.pop();
}
